# -*- coding: utf-8 -*-
"""专题二 · L200 —— 精讲版，从 L300 蒸馏出来。

L300（topic-02-L300.html）是 31,389 字主线 + 72 张图，讲完要两个小时。
L200 是同一个故事的精讲版：**四十张图上下，主线一万三千字上下。**

⛔ **不要再叫它「一小时版」。** 2026-09-03 拍板不砍 §3 的内容之后，主线就是
   80 分钟量级；页首那个 chip 是从讲义脚本累加算出来的真值，**它才是唯一真源**。
   历史上这里写死过「60 分钟 · 33 张图」，真值已经是 80 分钟 · 36 张图 ——&nbsp;
   两个都错，而且页面上没有任何东西会为此报错，它只是安静地在开篇撒谎。

════════════════════════════════════════════════════════════════
这个脚本为什么长这样：图从 L300 抽，文字自己写
════════════════════════════════════════════════════════════════
图（SVG ＋ figcaption）**整块从 L300 抽过来，一个字不改**。理由有两条：

  ① 图注本来就是精炼的。实测保留的这 33 张平均只有 95 字 ——
     L300 里那批四五百字的长图注（p27–p30、p32、p34、p20…），
     恰好全部在被砍的名单上。所以「缩图注」这件事根本不用做。
  ② **同一个职责不要两个载体。** 改了 L300 的图，L200 下次 build
     自动跟上；要是抄一份短版过来，两份迟早各自漂移。
     （这条是 2026-09-01 在 figC 上栽过一次才立的规矩。）

正文串词则完全重写 —— L200 跟 L300 本来就该说不一样的话，
这里没有「一个职责两个载体」的问题。

════════════════════════════════════════════════════════════════
⭐ 节号跟 L300 完全一致（§0–§9），这是故意的
════════════════════════════════════════════════════════════════
L200 砍掉的是小节，不是大节；被砍光的大节（第 8 节）宁可空着也不重排号。
两个好处：

  ① 听完 L200 想往下挖的人，可以拿着节号直接翻 L300 的同一节。
  ② 讲义、总纲 index.html、以及正文里那些「3.6 那张表」式的交叉引用，
     全都按这套号写死了；改号是一次全文波及的改动，收益却只有「好看」。

  ⚠️ 09-03 之前这儿的第一条理由是「figC 那张地图画着节号，改号就对不上」——
     **那张图的下半已经删了，这条理由跟着作废**，别再拿它当依据。

⛔ 所以**不要**顺手把 L200 的节号改成连续的 1234。

════════════════════════════════════════════════════════════════
⭐⭐ 全课主线：算子融合（2026-09-01 立）
════════════════════════════════════════════════════════════════
Chris 的原话：「算子融合是 top1 最重要、比任何事情都重要的一个话题，
硬件的研究最后都会落到算子融合上，要贯穿始终。」

⛔ 但**不要把它当成一个要加进来的新章节**。它是这门课一直在讲、
   只是一直没起名字的那件事。落点已经分布在各节里：

     §1  312 那条分界线，唯一用途就是判一次融合值不值得做
         （融合不改分子、只改分母 → 把算子从带宽侧推到算力侧）
     §2  「朴素 vs Flash」就是融合前后，强度差 1,024 倍
     §3.6 同一个融合，在两边分别怎么落地（块多大、谁来切）
     §5  「运行时还是编译期」问的正是：**融合这件事由谁决定** ← 全课收口
     §9  收尾也收在这上面

   名字在 §1 末尾第一次出现 —— 那条线刚画出来、还没用过的那一刻。
   早了没支撑（还不知道强度是什么），晚了后面几节就成了一串
   没有共同名字的技巧。

⛔ 往后每加一段内容，先问一句：**这段跟融合这条线是什么关系？**
   接不上的，多半就是该砍的。

════════════════════════════════════════════════════════════════
砍的账（哪些没了，为什么）
════════════════════════════════════════════════════════════════
  §1.1 §1.2   两颗芯片的封装全景 —— §3.1 的 ms-g1/ms-t1 讲的是同一件事，
              而且是显微镜原图，画得更细。**重复，整节删。**
  §1.3        十行完整对照表 —— 折进 §1 的手册块，主线不摊开。
  §2.5        形状对不齐的三笔账 —— 跟 §3.4「收缩维差 16 倍」同源，并过去。
  §2.8        所有算子回到 312 轴 —— 这是第三次讲 312（1.4 立、2.4 用）。
  §3.2 五张   p26/p27/p28/p29/p30，从「横竖代价不同」一路追问到位线田字格。
              精彩，但它是「再挖一层」，跟本课两个目标都不沾。
  §3.3 两张   g3/p31 —— 留 t3 那张「按问题对齐」的就够，它自带对比。
  §3.4 两张   p35/p36 —— p35 那笔账 §3.7 的 g8 又收了一遍，留 g8。
  §3.5 两张   g5/t5 —— 留 p37 那张「两块多出来的不在同一层」，它是总括。
  §4.2–4.4    NVL72 域内结构 / 跨芯片寻址 / 四种通信原语 —— 整个第 4 节里
              FlashAttention 出现 **0 次**（grep 过），它本来就是岔路。
              §4 在 L200 里整节折叠，只留边界（t8）和实测（p6）。
  §5.3        训练框架 p2 —— 并进 5.2 一句话。
  §5.7 两张   p32「为什么快」/ p34「收账」—— 留 p33 那张三层冻结的核心图，
              另外两张的结论压进正文两句。
  §6 两张     p12/p13「怎么比不对」—— 留 p14「该怎么比」，反例压成一句。
  §7 两张     p16 调优路径 / p17 留给读者的题 —— 留 p15（两个数）＋ p18（边界）。
  §8 整节     「我是怎么核数的」—— 方法论自曝，跟「硬件差别」和
              「FlashAttention 端到端」两个目标都不沾。指向 L300。
  §9.1 §9.2   9.2「答不了的」折叠；9.1 的 p22 留，正文压到一段。
  附录 A B    94.74 的算法 / 延伸阅读 —— 指向 L300。

════════════════════════════════════════════════════════════════
用法
════════════════════════════════════════════════════════════════
    cd Courses/tools && python3 topic02-build-L200.py

⛔ 先跑 topic02-port-microscope.py 把 L300 build 好，再跑这个 ——
   这个脚本是从 L300 的成品 HTML 里抽图的，L300 没更新就抽到旧图。
"""
import io
import os
import re
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "..", "WebPages", "topic-02-L300.html")
OUT = os.path.join(HERE, "..", "WebPages", "topic-02.html")

L300_URL = "topic-02-L300.html"
# ⚠️ 用到 `''' % L300_URL` 的那几段字符串里，**所有百分号都要写成 %%**。
#    2026-09-01 在 §6 写「30% 的运算是重算」时炸过一次，报的是
#    `unsupported format character` 加一个字节偏移量 —— 完全看不出是哪一行。
#    正文里百分号本来就多（利用率、占比），这个坑会反复来。
#    真嫌烦就把那几处改成 .replace("%s", L300_URL)，代价是少了格式化的报错检查。

_src = io.open(SRC, encoding="utf-8").read()


# ══════════════════════════════════════════════════════════════════════
# 一、从 L300 抽料
# ══════════════════════════════════════════════════════════════════════
def _head():
    """整个 <head>（含那份注入的 CSS）＋ <body> 开标签。

    连 CSS 一起抄，是为了让两份文档的观感永远一致 —— .fwide、details.aside、
    details.branch 这些类 L200 都要用，各留一份必然走散。
    """
    i = _src.index("</style>")
    return _src[:i + len("</style>")]


def _shared_defs():
    """显微镜那批图共用的 <defs>：marker（url(#aB) 这些）＋ SVG 内的 CSS 类。

    ⚠️ 它在 L300 里是一个独立的 <svg width="0" height="0">，藏在第一张
    ms 图前面。**抽图时必须连它一起搬** —— 少了它，marker 引用全部失效
    （箭头消失），.sec/.lbl/.sm 那些类也没了（字号全变成浏览器默认）。
    而这两样的失效都是**不报错**的，页面照常渲染，只是难看得莫名其妙。
    """
    key = '<svg width="0" height="0" style="position:absolute"'
    i = _src.index(key)
    return _src[i:_src.index("</svg>", i) + len("</svg>")]


# 图注需要改写的少数几张。**能不覆盖就不覆盖** —— 每覆盖一条，
# 就多一处「L300 改了、L200 没跟上」的可能。
CAP_OVERRIDE = {
    # ⛔ 2026-09-03 3.4 主线重写之后，t4 的原图注跟正文撞了：它把
    #    「head_dim=128 → GPU 切 8 条、TPU 只喂满一半、空着那半没人填」
    #    整条走了一遍，而这三步现在是 3.4 正文一步一步推的**主线**，
    #    图注就贴在它上面两行 —— 读者会连着读到两遍同一段推导。
    #    ⭐ 在 L300 里那句图注**必须留着**（L300 正文写的是「图上第三张卡
    #       把这个例子算完了」，正文本来就把例子委托给了图）。
    #       所以不改图脚本，只在 L200 覆盖。
    # ⛔ 同一天、同一个理由：3.5 正文重写之后，p37 的原图注把「不在同一层」
    #    和「两道门槛」整条又走了一遍，而它就贴在这段正文下面。
    #    ⭐ L300 那边照旧（它正文短，靠图注扛），只在 L200 覆盖。
    "ms-p37":
        "<b>上半张看「在哪一层」，下半张才是这张图的增量</b> ——&nbsp;"
        "<em>两道门槛并排放在一起，形状是一样的。</em>",

    "ms-t4":
        "<b>MXU 是 256×256，收缩维比 GPU 大 16 倍。</b>"
        "<em>这个差别落到一个真实的 <code>head_dim</code> 上会怎么样，正文接着走。</em>",

    # ⛔ 2026-09-03 图改了（下半那条六站路线整个删了，理由在图脚本里），
    #    图注跟着重写。原图注开头是「上半是根，下半是路」—— 下半一没，
    #    它就成了一句指着空气说话的话。**改图必须回头看图注**。
    "s012-figC":
        "<b>两种出身不是优劣，是两条路线</b> ——&nbsp;"
        "一条靠运行时现判，一条靠编译期算准。<b>分野只在一件事上：</b>"
        "你要跑的东西能不能提前知道。"
        "⭐ <b>右边那句「早就知道你要跑什么」是全课的根</b>："
        "后面每一节两边只要不一样，追到底都会回到这一句上。"
        "<em>——&nbsp;先带着它往下走，别急着记两边各有什么部件。</em>",

    # p33 原图注 333 字，是保留的 33 张里唯一的长图注。它长是因为
    # 在 L300 里它要独扛整个 5.7 小节（另外两张图被砍了）。这里把
    # 「为什么快」和「所以说明什么」两段挪进正文，图注只留三层那个答案。
    # ⛔ R3 加这两条。**它们在 L300 里是对的，在 L200 里是死引用** ——
    #    L300 的 §6＋§7 在本版合成了第 6 节，实测搬到了 6.3。
    #    改 port-microscope 的图注字典会把 L300 一起改坏，所以在这儿覆盖。
    "ms-p14":
        "<b>这是 6.3 的入场券 ——</b> 下一小节要摆两边的实测，"
        "而这张图决定了那组数该被当成什么。",

    "ms-p22":
        "八行取舍，两边各一句。<b>全课下来，两边同口径量过的只有 6.3 那 1.31 倍</b>"
        " ——而这句话在底带里，不在表里。<b>这张表整张是机制推理，它给不出倍数。</b>",

    "ms-p24":
        "<b>中间那个提问框是全课的骨架</b>，右格四句是唯一能带出门、"
        "换成别的两块硬件照样用的东西。<em>底带那三条限定，正文下面逐条展开。</em>",

    "ms-p33":
        "<b>反驳落到实处，是一个位置问题：到底哪一层被冻住了。</b><br>"
        "把通路切成三层：① 编排层（下一个 kernel 是什么）、"
        "② 落地层（块放到哪个 SM）、③ 发射层（下一拍执行哪条指令）。<br>"
        "⭐ 中间那一栏就是答案：<b>CUDA Graph 只冻住了 ①，②③ 一个都没动</b>。<br>"
        "graph 里每个节点仍然是一次正常的 kernel 启动 ——&nbsp;"
        "调度器、记分板、warp 槽、常驻上下文全都还在工作。<br>"
        "而 TPU 是<b>三层全冻</b>，且 ③ 冻到具体哪个周期、哪个发射槽。<br>"
        "<em>⚠️ 三层这个切法是讲法，不是术语。</em>",
}


# ── 图的 L200 专版 ────────────────────────────────────────────────────
# 绝大多数图两版通用（L200 的价值在于**少讲**，不在于**另画**）。
# 这里列的是少数几张：同一张图在 L300 是回查装置、在 L200 投到屏幕上是噪音。
#
# 实现：跑一次那张图的生成器（在临时目录里，不碰仓库），
# 拿它吐出的第二个文件把 lift 过来的 <svg> 整段换掉。
# 2026-09-03：这里原来只有一条 —— fig1-5 的 L200 专版（不带黄带）。
# 那张图连同脚本一起删了（理由见 §1.2 那段注释），所以表空了。
# ⚠️ 留着这个空表不是懒：机制还在用（fig() 会查它），下次再有
#    「同一张图两版」的需求时往里加一行就行，别再重新发明。
SVG_L200 = {}
_svg_cache = {}


def _l200_svg(key):
    if key not in _svg_cache:
        script, fn = SVG_L200[key]
        d = tempfile.mkdtemp(prefix="l200fig-")
        r = subprocess.run([sys.executable, os.path.join(HERE, script)],
                           cwd=d, capture_output=True, text=True)
        assert r.returncode == 0, "%s 跑挂了：\n%s" % (script, r.stderr)
        path = os.path.join(d, fn)
        assert os.path.isfile(path), "%s 没有吐出 %s" % (script, fn)
        _svg_cache[key] = io.open(path, encoding="utf-8").read().strip()
    return _svg_cache[key]


_FIG_SEEN = []


def fig(key, wide=None):
    """把 L300 里 id=key 的整个 <figure> 搬过来。

    wide=True/False 可以覆盖它的宽度类：L300 里 §0–§2 那批手写图是窄版
    （.fbox），§3 之后的显微镜图是宽版（.fbox.fwide）。L200 里两批混排，
    个别地方需要统一。不传就保持原样。
    """
    assert key not in _FIG_SEEN, "图 %s 被放了两次 —— L200 的全部意义就是不重复" % key
    _FIG_SEEN.append(key)

    # ⛔ 2026-09-03 这里原来是 `i = _src.index('id="key"')` 再往回 rindex("<figure")。
    #    看着没问题，实际是个哑弹：它**在整个 L300 文本里找第一处 id="key"**，
    #    而 L300 里的 HTML 注释也会出现这个串（我刚在 3.3b 的注释里写了
    #    「按 id="s012-fig3-4" 注入」）。于是 beg 落到注释里，
    #    block 从注释头一路吃到那个 </figure> —— **把整节正文都搬进了 L200**。
    #    症状极难看出来：不报错、图还在、只是 topic-02.html 无端胖了 28 KB。
    #    ⭐ 改成认**完整的开标签**，跟 topic02-inject-s012.py 的 _svg_span 同一套判据。
    m = re.search(r'<figure class="fbox(?: fwide)?" id="%s">' % re.escape(key), _src)
    assert m, "L300 里找不到 id=%s 的 figure 开标签" % key
    beg = m.start()
    end = _src.index("</figure>", m.end()) + len("</figure>")
    block = _src[beg:end]

    if key in CAP_OVERRIDE:
        # 保留 figcaption 尾巴上那个「—— 出自《显微镜》」的出处 span：
        # 它是引用，覆盖图注时丢掉就成了假原创。
        old = re.search(r"<figcaption>(.*?)</figcaption>", block, re.S).group(1)
        src_tail = re.search(r'<span class="msfrom">.*?</span>', old, re.S)
        new = CAP_OVERRIDE[key] + ("　" + src_tail.group(0) if src_tail else "")
        block = re.sub(r"<figcaption>.*?</figcaption>",
                       lambda _: "<figcaption>%s</figcaption>" % new, block, flags=re.S)

    if key in SVG_L200:
        i0 = block.index("<svg")
        i1 = block.index("</svg>") + len("</svg>")
        block = block[:i0] + _l200_svg(key) + block[i1:]

    # ⛔⛔ 2026-09-05：正文里「P-32 那笔账」「见 P-18 第 ③ 条」「两边都按 P-12 的口径取」
    #    这套图号出现 20 次，而**全篇没有任何一处告诉读者哪张图是 P-12**。
    #    学员原话：「这些引用对学员等于不存在。」
    #    → 在每张搬过来的图的图注开头印上它的号，引用当场就能落地。
    # ⭐ 形状：**作者脑子里的索引不等于读者手上的索引。** 图号是我在源码里用的 key，
    #   它从来没渲染出去过 —— 而我引用起来毫不犹豫，因为我知道它指谁。
    m2 = re.match(r'ms-([gtp])(\d+)$', key)
    if m2:
        badge = '<b class="fno">图 %s-%s</b>　' % (m2.group(1).upper(), m2.group(2))
        block = block.replace("<figcaption>", "<figcaption>" + badge, 1)

    if wide is True and "fwide" not in block[:120]:
        block = block.replace('class="fbox"', 'class="fbox fwide"', 1)
    elif wide is False:
        block = block.replace('class="fbox fwide"', 'class="fbox"', 1)
    return block


def lift(marker_start, marker_end):
    """从 L300 原样搬一段 HTML（用在那种「已经写好、没必要重写」的块上，
    目前只有 §1 那张十行手册表 ＋ 它的四条脚注）。"""
    i = _src.index(marker_start)
    j = _src.index(marker_end, i) + len(marker_end)
    return _src[i:j]


# ══════════════════════════════════════════════════════════════════════
# 二、正文
# ══════════════════════════════════════════════════════════════════════
# ⛔ 写这里的唯一规矩：**不复述图注里已经有的话。**
#    图注平均 95 字、密度很高，正文只干两件事：
#      ① 把上一张图的结论接到下一张图的问题上（一句，不是一段）；
#      ② 说图上没有的东西 —— 判据、第一手经验、以及「这一步在旅程的哪一站」。
#    L300 就是在这条线上失守的：过渡段逐字重复了紧接着那张图的图注开头。
# ══════════════════════════════════════════════════════════════════════
def body():
    s = []
    a = s.append

    # ── 开场热身：回顾专题一 ──────────────────────────────────────
    #
    # ⭐ 2026-09-05 Chris：「这个课一开始要不要回顾一下专题一？先问同学们几个问题，
    #    活跃一下气氛。从专题一里讲的重要的又好回答的问题，搞几道选择题，
    #    就像专题一里边一开始的那样，搞一道就行。」
    #
    # ⭐ 挑题的三条判据（下次加题照这个挑，别凭「哪个知识点重要」挑）：
    #    ① **是专题一自己列进「这一课带走这几条」的**，不是我从正文里现捞的 ——
    #       复习题问的必须是上一课明确要求记住的东西，否则它在考细节。
    #       这一道就是专题一收尾清单的第 01 条，原话：「关于 MoE：它省的是算力，
    #       不省显存。听到『激活只有 37B』就以为跟 37B 的稠密模型一样好养 ——
    #       完全不是。显存要装的还是 671B，一个字节都少不了。」
    #    ② **答错的那个选项要有人真的会选**。「两个都省」正是听到「激活 37B」
    #       之后最自然的误解 —— 一道全场都答对的题活跃不了气氛。
    #    ③ **答案要能当门推开** ——&nbsp;它把「显存」和「算力」掰成两样东西，
    #       而这一课要加的正是第三样：**带宽**。第 1 节第一件事就是算「算」和
    #       「搬」的兑换比。⛔ 不要挑一道答完就完了的题。
    #
    # ⚠️ 只放在 L200（要讲的那一版）。L300 是读的，不需要暖场。
    # ⛔ 只放一道。这是 Chris 明说的「搞一道就行」，也是对的 ——
    #    开场问三道，第三道的时候气氛已经从热身变成考试了。
    a("""
<section style="border-top:none;padding-bottom:8px"><div class="wrap">
  <div class="guess">
    <h3>开讲之前，先回一道上一课的题</h3>
    <p class="q">上一课我们拆了 <b>DeepSeek V3</b>：总参数 <b>671B</b>，
      但每个 token 只激活 <b>37B</b> ——&nbsp;这就是 <b>MoE</b>。<br>
      <span class="qs">于是很自然会想：既然只激活 37B，那它是不是就跟一个 37B 的稠密模型一样好养？<br>
      问的就是这个：<b>MoE 到底省下了什么？</b></span></p>
    <div class="opts">
      <button data-g="0">省显存，不省算力</button>
      <button data-g="1" data-right>省算力，不省显存</button>
      <button data-g="2">两个都省</button>
      <button data-g="3">都不省，只是换了个说法</button>
    </div>
    <div class="rev" id="rev">
      <p><b>省算力，不省显存。</b><br>
        <span class="qs">算的时候只走 37B 那条路，<b>算力是真省了</b>；
        可 671B 的权重<b>一个字节都不能少放</b> ——&nbsp;
        你不知道下一个 token 会挑中哪几个专家，所以全都得在显存里待着。
        <b>「激活 37B」跟「像 37B 一样好养」是两回事。</b></span></p>
      <p style="margin-bottom:0"><b>⭐ 而这道题真正想让大家听见的，是它背后那件事：</b>
        <span class="qs"><b>显存和算力是两样东西，会各走各的。</b>
        上一课整整一课都在分开算这两笔账。<br>
        <b>这一课要加的是第三样 ——&nbsp;带宽。</b>
        而且下面马上会看到：这三样里，真正决定一个算子快不快的，
        常常不是前两样。<em>第 1 节只做一件事，就是把「算」和「搬」的兑换比算出来。</em></span></p>
    </div>
  </div>
</div></section>
<script>
(function(){
  var box=document.querySelector('.guess'); if(!box) return;
  var rev=document.getElementById('rev');
  box.querySelectorAll('button').forEach(function(b){
    b.addEventListener('click', function(){
      box.querySelectorAll('button').forEach(function(x){x.classList.remove('picked','right');});
      b.classList.add('picked');
      box.querySelector('[data-right]').classList.add('right');
      rev.classList.add('on');
      rev.scrollIntoView({behavior:'smooth', block:'nearest'});
    });
  });
})();
</script>""")

    # ── 第 0 节 ───────────────────────────────────────────────────
